/* RPsy question bank. All items are original practice questions (simulated, not actual or leaked board questions).
   q(text, correct, wrong1, wrong2, wrong3, rationale): the correct answer is listed first; the app shuffles options at runtime. */
const q=(t,c,a,b,d,x)=>({q:t,o:[c,a,b,d],a:0,x});
const D=[
{id:"pers",p:"r",n:"Advance Theories of Personality",ic:"🧠",col:"#8b5cf6",
l:"Freud: id, ego, superego; defenses protect the ego from anxiety. Rogers: self-actualizing tendency; the self-concept grows through congruence. Bandura: reciprocal determinism among person, behavior, and environment; self-efficacy is belief in one’s capability to act. Jung proposed the collective unconscious and archetypes. The Five-Factor Model (Costa and McCrae) has openness, conscientiousness, extraversion, agreeableness, and neuroticism. Maslow’s order: physiological, safety, belongingness and love, esteem, self-actualization.",
c:[["Displacement","Redirecting an impulse from its real target to a safer substitute (Freud/A. Freud)"],["Self-efficacy","Belief in one’s capability to execute behavior needed for a goal (Bandura)"],["Collective unconscious","Jung: inherited layer of the psyche containing archetypes shared across humanity"],["Five-Factor Model","Openness, Conscientiousness, Extraversion, Agreeableness, Neuroticism (Costa and McCrae)"]],
q:[
{"q":"Who proposed that self-efficacy is a key determinant of behavior change?","o":["Albert Bandura","Julian Rotter","Walter Mischel","Martin Seligman"],"a":0,"x":["Correct. Bandura defined self-efficacy as belief in one’s capability to perform a task.","Rotter proposed locus of control, a related but different construct.","Mischel is known for person-situation debate and delay of gratification.","Seligman is known for learned helplessness and positive psychology."]},
{"q":"After being scolded by her boss, Mia snaps at her younger brother at home. This is:","o":["Displacement","Projection","Reaction formation","Sublimation"],"a":0,"x":["Correct. The aggression is shifted from the boss to a safer target.","Projection attributes one’s own unacceptable impulses to others.","Reaction formation expresses the opposite of the true impulse.","Sublimation channels impulses into socially valued activity."]},
{"q":"Which theorist proposed the collective unconscious and archetypes?","o":["Carl Jung","Alfred Adler","Karen Horney","Gordon Allport"],"a":0,"x":["Correct. Jung described an inherited layer of the unconscious shared across humanity.","Adler developed individual psychology: inferiority feelings and striving for superiority.","Horney emphasized basic anxiety and neurotic needs within a social-cultural view.","Allport is a trait theorist who described cardinal, central, and secondary dispositions."]},
{"q":"Which is a factor in the Five-Factor Model of personality?","o":["Conscientiousness","Psychoticism","Machiavellianism","Introversion"],"a":0,"x":["Correct. The five are openness, conscientiousness, extraversion, agreeableness, and neuroticism.","Psychoticism belongs to Eysenck’s model.","Machiavellianism is part of the Dark Triad, not the Five-Factor Model.","Introversion is the low pole of extraversion, not a separate factor."]},
{"q":"In Maslow’s hierarchy, which need comes immediately after safety needs?","o":["Belongingness and love","Esteem","Self-actualization","Physiological"],"a":0,"x":["Correct. The order is physiological, safety, belongingness and love, esteem, self-actualization.","Esteem comes after belongingness and love.","Self-actualization sits at the top.","Physiological needs are the base, before safety."]}
]},
{id:"assess",p:"rg",n:"Psychological Assessment",ic:"📊",col:"#06b6d4",
l:"Reliability is consistency (test-retest, internal consistency, inter-rater). Validity is whether scores support intended interpretations (content, criterion, construct). A test can be reliable without being valid, but not valid without being reliable. T-scores have a mean of 50 and SD of 10. The Rorschach is a projective technique; the MMPI-2 is an objective self-report inventory. Item difficulty p is the proportion answering correctly.",
c:[["Test-retest reliability","Stability of scores across two administrations of the same test over time"],["Concurrent validity","Correlation of a new test with an established criterion measured at about the same time"],["T-score","Standard score with mean 50 and SD 10"],["Item difficulty (p)","Proportion of examinees who answer an item correctly"]],
q:[
{"q":"A researcher gives the same test to the same group two weeks apart and correlates the scores. This estimates:","o":["Test-retest reliability","Internal consistency","Construct validity","Inter-rater reliability"],"a":0,"x":["Correct. It estimates score stability over time.","Internal consistency uses one administration (e.g., Cronbach’s alpha).","Construct validity needs evidence about the underlying trait, not one correlation over time.","Inter-rater reliability compares different scorers."]},
{"q":"A new depression scale is correlated with a clinician diagnosis made the same week. This is evidence of:","o":["Concurrent validity","Predictive validity","Face validity","Split-half reliability"],"a":0,"x":["Correct. The criterion is measured at about the same time.","Predictive validity would require the criterion to be measured later.","Face validity is only apparent relevance, not a correlation.","Split-half is a reliability method."]},
{"q":"A T-score distribution has a mean and standard deviation of:","o":["50 and 10","100 and 15","0 and 1","10 and 3"],"a":0,"x":["Correct. T = 50 + 10z.","Deviation IQ scores commonly use a mean of 100 and SD of 15.","Z-scores have a mean of 0 and SD of 1.","Wechsler subtest scaled scores use a mean of 10 and SD of 3."]},
{"q":"Which is a projective technique?","o":["Rorschach Inkblot Test","MMPI-2","WAIS-IV","Beck Depression Inventory"],"a":0,"x":["Correct. Ambiguous stimuli elicit responses interpreted as reflecting personality.","The MMPI-2 is an objective self-report inventory.","The WAIS-IV measures intelligence through performance tasks.","The BDI is a self-report symptom inventory."]},
{"q":"An item answered correctly by 90% of examinees is best described as:","o":["Very easy","Very difficult","Moderately difficult","Perfectly discriminating"],"a":0,"x":["Correct. The difficulty index p is the proportion answering correctly, so a high p means an easy item.","A very difficult item would have a low p, near .10.","Moderate difficulty is around p = .50.","Discrimination is a separate index and is not determined by difficulty alone."]}
]},
{id:"abn",p:"r",n:"Advance Abnormal Psychology",ic:"🌀",col:"#ec4899",
l:"DSM-5-TR organizes disorders by criteria and duration. Persistent depressive disorder: depressed mood most days for at least 2 years in adults. Panic disorder: recurrent unexpected panic attacks plus at least 1 month of persistent concern or behavior change. Schizophrenia positive symptoms are added experiences (hallucinations, delusions); negative symptoms are reductions (flat affect, alogia, avolition). Bipolar I requires at least one manic episode.",
c:[["Persistent depressive disorder","Depressed mood most of the day, more days than not, for at least 2 years in adults"],["Panic disorder","Recurrent unexpected panic attacks plus 1+ month of worry or avoidance"],["Positive symptoms","Added experiences in schizophrenia, such as hallucinations and delusions"],["Acute stress disorder","Trauma symptoms lasting 3 days to 1 month after exposure"]],
q:[
{"q":"An adult reports low mood on most days for the past three years, with no manic episodes. The best fit is:","o":["Persistent depressive disorder","Major depressive disorder, single episode","Cyclothymic disorder","Adjustment disorder"],"a":0,"x":["Correct. Chronic low mood of 2+ years in adults matches this.","A single episode is typically shorter, with more acute symptoms.","Cyclothymia involves hypomanic symptoms too.","Adjustment disorder follows an identifiable stressor within 3 months and is time-limited."]},
{"q":"Which feature is required for panic disorder?","o":["Recurrent unexpected panic attacks","Fear of a specific object","Compulsive rituals","Fear of negative evaluation"],"a":0,"x":["Correct. Along with persistent concern or behavior change for 1+ month.","That describes specific phobia.","That describes OCD.","That describes social anxiety disorder."]},
{"q":"Which is a positive symptom of schizophrenia?","o":["Hallucinations","Flat affect","Alogia","Avolition"],"a":0,"x":["Correct. Hallucinations and delusions are added experiences, hence positive.","Flat affect is a negative symptom (diminished emotional expression).","Alogia (reduced speech) is a negative symptom.","Avolition (reduced motivation) is a negative symptom."]},
{"q":"Trauma-related symptoms lasting from 3 days to 1 month after exposure best fit:","o":["Acute stress disorder","Posttraumatic stress disorder","Adjustment disorder","Generalized anxiety disorder"],"a":0,"x":["Correct. Acute stress disorder spans 3 days to 1 month after the trauma.","PTSD requires symptoms lasting more than 1 month.","Adjustment disorder follows a stressor that need not be traumatic exposure.","GAD involves excessive worry for at least 6 months."]},
{"q":"A diagnosis of bipolar I disorder requires at least one lifetime:","o":["Manic episode","Major depressive episode","Hypomanic episode with a major depressive episode","Two years of low mood"],"a":0,"x":["Correct. At least one manic episode defines bipolar I.","A depressive episode is common but not required for bipolar I.","Hypomania plus major depression defines bipolar II.","Two years of low mood describes persistent depressive disorder."]}
]},
{id:"ethr",p:"r",sup:1,n:"Law & Ethics: RA 10029",ic:"⚖️",col:"#f59e0b",
l:"RA 10029, the Philippine Psychology Act of 2009, regulates the practice of psychology and created the Professional Regulatory Board of Psychology under the PRC. Confidentiality is a core duty, with limits, such as clear and imminent danger to self or others and legal requirements.",
c:[["RA 10029","Philippine Psychology Act of 2009: regulates the practice of psychology"],["Limits of confidentiality","Imminent danger to self/others, legal mandates, and informed exceptions explained at the start"]],
q:[
{"q":"Which law regulates the practice of psychology in the Philippines?","o":["RA 10029","RA 9258","RA 7610","RA 10173"],"a":0,"x":["Correct. The Philippine Psychology Act of 2009.","RA 9258 is the Guidance and Counseling Act of 2004.","RA 7610 concerns child protection.","RA 10173 is the Data Privacy Act, relevant to records but not the practice law."]},
{"q":"A client discloses a specific plan to seriously harm a named person. The psychologist should:","o":["Take protective action within ethical and legal limits","Keep it absolutely confidential","Wait until the next session","Terminate therapy immediately"],"a":0,"x":["Correct. Assess risk, consult, and act to protect, disclosing only what is necessary.","Confidentiality is not absolute when danger is clear and imminent.","Delay may risk harm.","Abrupt termination is abandonment and does not reduce risk."]}
]},
{id:"dev",p:"rg",sup:1,n:"Developmental Psychology",ic:"🌱",col:"#22c55e",
l:"Piaget: sensorimotor, preoperational, concrete operational, formal operational. Erikson: eight psychosocial crises; adolescence is identity vs. role confusion.",
c:[["Object permanence","Understanding that objects exist when out of sight; develops in Piaget’s sensorimotor stage"],["Identity vs. role confusion","Erikson’s adolescent crisis"]],
q:[
{"q":"Object permanence is mastered mainly in which Piagetian stage?","o":["Sensorimotor","Preoperational","Concrete operational","Formal operational"],"a":0,"x":["Correct. Roughly birth to 2 years.","Preoperational is marked by symbolic thought and egocentrism.","Concrete operational brings conservation and logic about concrete objects.","Formal operational brings abstract reasoning."]},
{"q":"Which Eriksonian crisis is central in adolescence?","o":["Identity vs. role confusion","Trust vs. mistrust","Industry vs. inferiority","Generativity vs. stagnation"],"a":0,"x":["Correct. Adolescents explore roles to form a coherent identity.","That is infancy.","That is school age.","That is middle adulthood."]}
]},
{id:"cth",p:"rg",n:"Counseling Theories & Psychotherapy",ic:"💬",col:"#3b82f6",
l:"Person-centered counseling relies on congruence, unconditional positive regard, and accurate empathy. CBT (Beck) targets automatic thoughts and cognitive distortions such as overgeneralization and catastrophizing. Wolpe: systematic desensitization. Ellis: REBT and the ABC model. Perls: Gestalt therapy and experiments such as the empty chair.",
c:[["Core conditions","Rogers: congruence, unconditional positive regard, empathic understanding"],["Overgeneralization","Drawing a broad conclusion from a single event"],["REBT ABC model","Ellis: Activating event, Beliefs, Consequences"],["Systematic desensitization","Wolpe: relaxation paired with graded exposure to feared stimuli"]],
q:[
{"q":"Which is NOT one of Rogers’ core conditions?","o":["Interpreting unconscious conflicts","Congruence","Unconditional positive regard","Empathic understanding"],"a":0,"x":["Correct. Interpretation of unconscious material belongs to psychodynamic work.","It is a core condition (genuineness).","It is a core condition.","It is a core condition."]},
{"q":"After one failed quiz, Ana thinks, “I always fail at everything.” In CBT this is:","o":["Overgeneralization","Personalization","Mind reading","Emotional reasoning"],"a":0,"x":["Correct. One event is stretched into a global rule.","Personalization blames oneself for external events.","Mind reading assumes others’ thoughts.","Emotional reasoning treats feelings as proof."]},
{"q":"Systematic desensitization, pairing relaxation with graded exposure, was developed by:","o":["Joseph Wolpe","B. F. Skinner","Albert Ellis","Fritz Perls"],"a":0,"x":["Correct. Wolpe built it on counterconditioning (reciprocal inhibition).","Skinner developed operant conditioning principles.","Ellis developed REBT.","Perls co-founded Gestalt therapy."]},
{"q":"In Ellis’s ABC model, the letter B stands for:","o":["Beliefs","Behavior","Biases","Boundaries"],"a":0,"x":["Correct. A is the activating event, B the beliefs, and C the emotional and behavioral consequences.","Behavior is not the B; behavioral outcomes fall under C, consequences.","Biases is not a term in the model.","Boundaries is not part of the model."]},
{"q":"The empty chair technique is most associated with:","o":["Gestalt therapy","Psychoanalysis","Person-centered therapy","Cognitive therapy"],"a":0,"x":["Correct. It is a classic Gestalt experiment for unfinished business.","Psychoanalysis uses free association and interpretation.","Person-centered therapy relies on the core conditions, not staged experiments.","Cognitive therapy uses thought records and Socratic questioning."]}
]},
{id:"ethg",p:"g",sup:1,n:"Law & Ethics: RA 9258",ic:"⚖️",col:"#f59e0b",
l:"RA 9258, the Guidance and Counseling Act of 2004, professionalizes guidance and counseling and requires licensure under the PRC. Counselors avoid exploitative dual relationships and protect client welfare.",
c:[["RA 9258","Guidance and Counseling Act of 2004"],["Dual relationship","A second role with a client that risks impaired judgment or exploitation"]],
q:[
{"q":"Which law professionalized guidance and counseling in the Philippines?","o":["RA 9258","RA 10029","RA 8981","RA 9155"],"a":0,"x":["Correct. The Guidance and Counseling Act of 2004.","RA 10029 governs psychology practice.","RA 8981 is the PRC Modernization Act.","RA 9155 is the Governance of Basic Education Act."]},
{"q":"A counselor is asked to date a former client the week after termination. The ethical response is to:","o":["Decline and avoid exploitative relationships","Proceed if the client agrees","Wait one day","Ask a colleague to hide it"],"a":0,"x":["Correct. Protect client welfare and avoid boundary violations.","Consent does not remove the power imbalance.","A short delay does not address the risk.","Concealment compounds the violation."]}
]},
{id:"res",p:"rg",sup:1,n:"Research & Statistics",ic:"📈",col:"#14b8a6",
l:"A p-value is the probability of data at least this extreme if the null is true; it is not the probability the null is true. Use an independent-samples t-test for two unrelated group means.",
c:[["p-value","Probability of results at least this extreme assuming the null hypothesis is true"],["Independent t-test","Compares means of two unrelated groups"]],
q:[
{"q":"p = .03 means:","o":["Results this extreme would occur 3% of the time if the null were true","The null is 3% likely true","The effect is large","There is a 97% chance of replication"],"a":0,"x":["Correct. It is a conditional probability under the null.","A common misreading; p is conditional on the null.","p does not measure effect size.","p does not give replication probability."]},
{"q":"Compare anxiety scores of two separate groups, treated vs. control. Best test?","o":["Independent-samples t-test","Paired t-test","Chi-square","Pearson r"],"a":0,"x":["Correct. Two unrelated groups, a continuous outcome.","Paired suits the same people measured twice.","Chi-square is for categorical frequencies.","Pearson r assesses association, not a group difference."]}
]},
{id:"gfound",p:"g",n:"Foundations of Guidance",ic:"🧭",col:"#f97316",
l:"Guidance is an organized set of services that helps learners with personal, educational, and vocational development. Core services: orientation, individual inventory, information, counseling, placement, follow-up, and referral. Frank Parsons, the father of vocational guidance, founded Boston’s Vocation Bureau (1908); his trait-and-factor approach matches self-knowledge with occupational knowledge through true reasoning.",
c:[["Individual inventory service","Systematic collection of data about each learner (family, academic, health, interests) to understand and help them"],["Trait-and-factor (Parsons)","Match knowledge of self with knowledge of occupations through true reasoning"]],
q:[
{"q":"Who is called the father of vocational guidance?","o":["Frank Parsons","Carl Rogers","John Holland","Donald Super"],"a":0,"x":["Correct. He founded the Vocation Bureau in Boston and proposed trait-and-factor matching.","Rogers developed person-centered therapy.","Holland proposed the RIASEC model of vocational types.","Super proposed a life-span, life-space career development theory."]},
{"q":"A counselor compiles learners’ family background, grades, health data, and interests into cumulative records. This is the:","o":["Individual inventory service","Placement service","Follow-up service","Information service"],"a":0,"x":["Correct. It gathers data to know each learner.","Placement helps learners enter suitable courses, jobs, or activities.","Follow-up checks on learners after services or placement.","Information provides educational and occupational facts."]},
{"q":"A learner needs long-term treatment for severe depression beyond a school counselor’s competence. The proper guidance service is:","o":["Referral","Placement","Orientation","Individual inventory"],"a":0,"x":["Correct. Refer to a qualified professional, with consent and follow-up.","Placement matches learners to opportunities, not treatment.","Orientation introduces learners to school and services.","Inventory gathers data and does not provide treatment."]}
]},
{id:"gorg",p:"g",n:"Organization and Administration of Guidance Services",ic:"🏫",col:"#6366f1",
l:"A guidance program starts with needs assessment, then sets objectives, plans services, assigns roles, implements, and evaluates process and outcomes. Evaluation results feed program improvement. Records are kept confidential and accessible only to authorized persons.",
c:[["Needs assessment","Systematic gathering of learner and community needs data to plan program objectives and services"],["Program evaluation","Judging a program’s process and outcomes in order to improve it"]],
q:[
{"q":"What usually comes first when planning a guidance program?","o":["Conducting a needs assessment","Hiring more staff","Evaluating outcomes","Printing forms"],"a":0,"x":["Correct. Needs data shape the objectives and services.","Staffing follows the plan.","Outcome evaluation comes after implementation.","Forms are tools, not the first step."]},
{"q":"A counselor compares bullying incident rates before and after an anti-bullying program. This is:","o":["Outcome evaluation","Needs assessment","Orientation","Placement"],"a":0,"x":["Correct. It judges the results of the program.","Needs assessment precedes the program.","Orientation introduces services.","Placement matches learners to opportunities."]},
{"q":"A teacher asks to read a learner’s counseling notes out of curiosity. The best response is to:","o":["Decline, explaining that counseling records are confidential, and share only what is necessary and permitted","Share all notes","Share a summary informally","Let the teacher read them in the office"],"a":0,"x":["Correct. Disclosure follows consent, necessity, and legal limits.","Records are not open to casual access.","Informal summaries still breach confidentiality.","Access in the office is still access."]}
]},
{id:"ggrp",p:"g",n:"Group Process and Program Development",ic:"👥",col:"#e11d48",
l:"Tuckman’s stages: forming, storming, norming, performing, adjourning. Yalom’s curative factors include instillation of hope, universality, imparting information, altruism, cohesiveness, and catharsis. Group guidance is usually preventive and informational; group counseling is more personal and works with smaller groups. Leaders explain confidentiality and its limits, since members cannot be guaranteed to keep it.",
c:[["Tuckman stages","Forming, storming, norming, performing, adjourning"],["Universality","Yalom: realizing others share similar problems, which reduces isolation"]],
q:[
{"q":"Members challenge the leader and conflict surfaces. Which Tuckman stage is this?","o":["Storming","Forming","Norming","Performing"],"a":0,"x":["Correct. Conflict and resistance mark storming.","Forming is polite and tentative.","Norming sets cooperation and shared rules.","Performing is productive work toward goals."]},
{"q":"A member says, “I thought I was the only one who felt this way.” Which Yalom factor?","o":["Universality","Catharsis","Altruism","Imparting information"],"a":0,"x":["Correct. Seeing shared experience reduces isolation.","Catharsis is emotional release.","Altruism is helping others.","Imparting information is advice or teaching."]},
{"q":"Which statement about confidentiality in group counseling is most accurate?","o":["The leader explains confidentiality and its limits, and cannot guarantee members’ compliance","The leader can guarantee members will not disclose","Confidentiality does not apply in groups","Only the leader is bound"],"a":0,"x":["Correct. Honest informed consent is the standard.","Members are not bound the way professionals are, so no guarantee is possible.","It applies; its limits should be explained.","Members are asked to respect it too."]}
]}
];
